update vm_horn_device_info_t set device_name = #{item.deviceName}, device_status = #{item.onlineStatus},
device_type = #{item.catalogType},
site_code = #{item.siteCode}, site_name= #{item.siteName}, province_code = #{item.provinceCode}, city_code = #{item.cityCode}, county_code = #{item.countyCode}, town_code = #{item.townCode}, location = #{item.address}, longitude = #{item.longitude}, latitude = #{item.latitude}, area_code = #{item.dept}, adm_code = #{item.adminArea}, manufacturer_code = #{item.manufacturer}, model_code = #{item.deviceModel}, height = #{item.hangingHeight}, app_mod_flag = #{item.appModFlag}, modifier = #{item.updateBy}, delete_flag = #{item.delFlag}, access_node = #{item.locationCode}, update_time = DATE_FORMAT(#{item.updateTime}, '%Y-%m-%d %H:%i:%S') where device_code = #{item.deviceCode}
